statistiques_notes.c<pre><code>#include &lt;stdio.h&gt;

int main(void)
{
    int nb_etudiants = 0;

    printf("=========================================\n");
    printf("   GESTION DES NOTES DE LA PROMOTION     \n");
    printf("=========================================\n\n");

    // 1. Contrôle du nombre d'étudiants
    do
    {
        printf("Nombre d'etudiants dans la classe : ");
        scanf("%d", &amp;nb_etudiants);
        if (nb_etudiants &lt;= 0)
        {
            printf("Veuillez saisir un effectif superieur a 0.\n");
        }
    } while (nb_etudiants &lt;= 0);

    float somme = 0.0f;
    float note_min = 20.0f; // Initialisée au maximum possible
    float note_max = 0.0f;  // Initialisée au minimum possible
    int nb_admis = 0;

    // 2. Boucle de saisie des notes individuelles
    for (int i = 1; i &lt;= nb_etudiants; i++)
    {
        float note_courante = -1.0f;

        do
        {
            printf("Note de l'etudiant n°%d / %d (0 a 20) : ", i, nb_etudiants);
            scanf("%f", &amp;note_courante);
            if (note_courante &lt; 0.0f || note_courante &gt; 20.0f)
            {
                printf("Erreur : La note doit etre comprise entre 0 et 20.\n");
            }
        } while (note_courante &lt; 0.0f || note_courante &gt; 20.0f);

        // Cumul pour la moyenne
        somme += note_courante;

        // Mise à jour des extrema
        if (note_courante &lt; note_min)
        {
            note_min = note_courante;
        }
        if (note_courante &gt; note_max)
        {
            note_max = note_courante;
        }

        // Décompte des admissions
        if (note_courante &gt;= 10.0f)
        {
            nb_admis++;
        }
    }

    // 3. Calculs finaux et affichage
    float moyenne = somme / (float)nb_etudiants;
    float taux_reussite = ((float)nb_admis / (float)nb_etudiants) * 100.0f;

    printf("\n=========================================\n");
    printf("         RESULTATS DE LA PROMOTION       \n");
    printf("=========================================\n");
    printf("Effectif total       : %d etudiants\n", nb_etudiants);
    printf("Moyenne de la classe : %.2f / 20\n", moyenne);
    printf("Note minimale        : %.2f / 20\n", note_min);
    printf("Note maximale        : %.2f / 20\n", note_max);
    printf("Etudiants admis      : %d (%.1f %%)\n", nb_admis, taux_reussite);
    printf("=========================================\n");

    return 0;
}
