int main(void)
{
    int limite = 0;

    printf("Entrez un nombre limite N (&gt;= 2) : ");
    if (scanf("%d", &amp;limite) != 1 || limite &lt; 2)
    {
        printf("Erreur : Valeur non valide.\n");
        return 1;
    }

    printf("\nNombres premiers compris entre 2 et %d :\n", limite);
    int total_premiers = 0;

    for (int n = 2; n &lt;= limite; n++)
    {
        bool est_premier = true;

        // Optimisation : tester jusqu'à d * d &lt;= n (équivaut à d &lt;= racine de n)
        for (int d = 2; d * d &lt;= n; d++)
        {
            if (n % d == 0)
            {
                est_premier = false;
                break; // Dès qu'un diviseur est trouvé, on arrête
            }
        }

        if (est_premier)
        {
            printf("%d ", n);
            total_premiers++;
        }
    }

    printf("\n\nTotal trouve : %d nombres premiers.\n", total_premiers);
    return 0;
}
