math_utils.c<pre><code>#include "math_utils.h"

bool EstPair(int n)
{
    return (n % 2 == 0);
}

bool EstPremier(int n)
{
    if (n &lt; 2) return false;
    for (int d = 2; d * d &lt;= n; d++)
    {
        if (n % d == 0) return false;
    }
    return true;
}

double Puissance(double base, int exposant)
{
    if (exposant == 0) return 1.0;

    double resultat = 1.0;
    for (int i = 0; i &lt; exposant; i++)
    {
        resultat *= base;
    }
    return resultat;
}

long long SommeConsecutive(int n)
{
    if (n &lt;= 0) return 0;
    return ((long long)n * (n + 1)) / 2;
}
</code></pre>

