recursivite_avancee.c<pre><code>#include &lt;stdio.h&gt;

/* 1. Affichage récursif de la base 2 */
void AfficherBinaire(unsigned int n)
{
    // Cas récursif : afficher les bits supérieurs d'abord
    if (n &gt; 1)
    {
        AfficherBinaire(n / 2);
    }

    // Cas de base / affichage du bit de poids faible au dépilement
    printf("%u", n % 2);
}

/* 2. Résolution des Tours de Hanoï */
void ResoudreHanoi(int n, char depart, char auxiliaire, char arrivee)
{
    // Cas de base : déplacer un seul disque
    if (n == 1)
    {
        printf("Deplacer le disque 1 de %c vers %c\n", depart, arrivee);
        return;
    }

    // Étape A : Déplacer n - 1 disques du départ vers l'auxiliaire
    ResoudreHanoi(n - 1, depart, arrivee, auxiliaire);

    // Étape B : Déplacer le plus grand disque restant
    printf("Deplacer le disque %d de %c vers %c\n", n, depart, arrivee);

    // Étape C : Déplacer les n - 1 disques de l'auxiliaire vers l'arrivée
    ResoudreHanoi(n - 1, auxiliaire, depart, arrivee);
}

int main(void)
{
    unsigned int valeur = 43;

    printf("--- CONVERSION BINAIRE RECURSIVE ---\n");
    printf("Decimal : %u -&gt; Binaire : ", valeur);
    AfficherBinaire(valeur);
    printf("\n\n");

    printf("--- RESOLUTION TOURS DE HANOI (3 DISQUES) ---\n");
    ResoudreHanoi(3, 'A', 'B', 'C');

    return 0;
}
</code></pre>

