long long Factorielle(int n)
{
    // 1. CAS DE BASE : 0! = 1
    if (n &lt;= 0)
    {
        return 1;
    }

    // 2. CAS RÉCURSIF : n * (n - 1)!
    return n * Factorielle(n - 1);
}

