produit_matriciel.c<pre><code>#include &lt;stdio.h&gt;

#define N 2 // Lignes de A
#define M 3 // Colonnes de A et Lignes de B
#define P 2 // Colonnes de B

int main(void)
{
    int A[N][M] = {
        {1, 2, 3},
        {4, 5, 6}
    };

    int B[M][P] = {
        {7, 8},
        {9, 1},
        {2, 3}
    };

    // Matrice résultat C de dimension N x P (2 x 2), initialisée à zéro
    int C[N][P] = {0};

    // 1. Parcours des lignes de A
    for (int i = 0; i &lt; N; i++)
    {
        // 2. Parcours des colonnes de B
        for (int k = 0; k &lt; P; k++)
        {
            // 3. Calcul de la somme des produits
            for (int j = 0; j &lt; M; j++)
            {
                C[i][k] += A[i][j] * B[j][k];
            }
        }
    }

    // Affichage de la matrice produit
    printf("Produit matriciel C = A x B (%d x %d) :\n", N, P);
    for (int i = 0; i &lt; N; i++)
    {
        printf("| ");
        for (int k = 0; k &lt; P; k++)
        {
            printf("%4d ", C[i][k]);
        }
        printf("|\n");
    }

    return 0;
}
