tri_a_bulles.c<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdbool.h&gt;

void AfficherTableau(const int tab[], int taille)
{
    printf("[ ");
    for (int i = 0; i &lt; taille; i++)
    {
        printf("%d ", tab[i]);
    }
    printf("]\n");
}

void TrierBulles(int tab[], int taille)
{
    for (int i = 0; i &lt; taille - 1; i++)
    {
        bool echange_effectue = false;

        // Les i derniers éléments sont déjà à leur place définitive
        for (int j = 0; j &lt; taille - 1 - i; j++)
        {
            if (tab[j] &gt; tab[j + 1])
            {
                // Échange des deux éléments
                int temporaire = tab[j];
                tab[j] = tab[j + 1];
                tab[j + 1] = temporaire;

                echange_effectue = true;
            }
        }

        // Si aucun échange n'a eu lieu pendant tout le tour, le tableau est déjà trié !
        if (!echange_effectue)
        {
            break;
        }
    }
}

int main(void)
{
    int donnees[] = {64, 34, 25, 12, 22, 11, 90};
    int taille = sizeof(donnees) / sizeof(donnees[0]);

    printf("Tableau initial  : ");
    AfficherTableau(donnees, taille);

    TrierBulles(donnees, taille);

    printf("Tableau ordonne  : ");
    AfficherTableau(donnees, taille);

    return 0;
}
</code></pre>

