float CalculerMoyenne(const float tab[], int taille)
{
    float somme = 0.0f;
    for (int i = 0; i &lt; taille; i++)
    {
        somme += tab[i];
    }
    return somme / (float)taille;
}

int CompterAdmis(const float tab[], int taille)
{
    int compteur = 0;
    for (int i = 0; i &lt; taille; i++)
    {
        if (tab[i] &gt;= 10.0f)
        {
            compteur++;
        }
    }
    return compteur;
