inversion_pointeurs.c<pre><code>#include &lt;stdio.h&gt;

void InverserTableau(int *tab, int taille)
{
    if (tab == NULL || taille &lt;= 1) return;

    int *gauche = tab;
    int *droite = tab + taille - 1;

    while (gauche &lt; droite)
    {
        // Échange des valeurs déréférencées
        int temporaire = *gauche;
        *gauche = *droite;
        *droite = temporaire;

        // Déplacement convergent des pointeurs
        gauche++;
        droite--;
    }
}

void AfficherTableau(const int *tab, int taille)
{
    printf("[ ");
    for (int i = 0; i &lt; taille; i++)
    {
        printf("%d ", tab[i]);
    }
    printf("]\n");
}

int main(void)
{
    int suite[] = {10, 20, 30, 40, 50, 60};
    int n = sizeof(suite) / sizeof(suite[0]);

    printf("Tableau avant inversion : ");
    AfficherTableau(suite, n);

    InverserTableau(suite, n);

    printf("Tableau apres inversion : ");
    AfficherTableau(suite, n);

    return 0;
}
