typedef struct
{
    double x;
    double y;
} Point2D;

typedef struct
{
    Point2D centre; // Structure imbriquée
    double rayon;
} Cercle;

double CalculerDistance(Point2D p1, Point2D p2)
{
    double dx = p2.x - p1.x;
    double dy = p2.y - p1.y;
    return sqrt(dx * dx + dy * dy);
}

bool EstDansCercle(Point2D p, Cercle c)
{
    double d = CalculerDistance(p, c.centre);
    return (d &lt;= c.rayon);
