bool EstPalindrome(const char *str)
{
    if (str == NULL) return false;

    int gauche = 0;
    int droite = (int)strlen(str) - 1;

    while (gauche &lt; droite)
    {
        // Comparaison insensible à la casse avec tolower()
        if (tolower((unsigned char)str[gauche]) != tolower((unsigned char)str[droite]))
        {
            return false; // Différence détectée : pas un palindrome
        }
        gauche++;
        droite--;
    }

    return true; // Tous les caractères symétriques correspondent
}

int main(void)
{
    char mot[50];

    printf("Entrez un mot a verifier : ");
    if (fgets(mot, sizeof(mot), stdin) != NULL)
    {
        // Remplacement du '\n' final
        mot[strcspn(mot, "\n")] = '\0';

        if (EstPalindrome(mot))
        {
            printf("Le mot \"%s\" est un PALINDROME parfait !\n", mot);
        }
        else
        {
            printf("Le mot \"%s\" N'EST PAS un palindrome.\n", mot);
        }
    }

    return 0;
}
