analyseur_texte.c<pre><code>#include &lt;stdio.h&gt;
#include &lt;string.h&gt;
#include &lt;ctype.h&gt;
#include &lt;stdbool.h&gt;

void AnalyserTexte(const char *texte)
{
    int nb_voyelles = 0;
    int nb_consonnes = 0;
    int nb_chiffres = 0;
    int nb_mots = 0;
    bool dans_un_mot = false;

    for (int i = 0; texte[i] != '\0'; i++)
    {
        unsigned char c = (unsigned char)texte[i];

        // 1. Détection des chiffres
        if (isdigit(c))
        {
            nb_chiffres++;
        }
        // 2. Détection des lettres
        else if (isalpha(c))
        {
            char minuscule = (char)tolower(c);
            if (minuscule == 'a' || minuscule == 'e' || minuscule == 'i' ||
                minuscule == 'o' || minuscule == 'u' || minuscule == 'y')
            {
                nb_voyelles++;
            }
            else
            {
                nb_consonnes++;
            }
        }

        // 3. Détection et comptage des mots
        if (!isspace(c))
        {
            if (!dans_un_mot)
            {
                dans_un_mot = true;
                nb_mots++;
            }
        }
        else
        {
            dans_un_mot = false;
        }
    }

    printf("--- RAPPORT D'ANALYSE TEXTUELLE ---\n");
    printf("Nombre de mots      : %d\n", nb_mots);
    printf("Nombre de voyelles  : %d\n", nb_voyelles);
    printf("Nombre de consonnes : %d\n", nb_consonnes);
    printf("Nombre de chiffres  : %d\n", nb_chiffres);
    printf("------------------------------------\n");
}

int main(void)
{
    char phrase[] = "Le langage C a ete cree en 1972 par Dennis Ritchie.";

    printf("Texte analyse :\n\"%s\"\n\n", phrase);
    AnalyserTexte(phrase);

    return 0;
}
