chiffre_cesar.c<pre><code>#include &lt;stdio.h&gt;
#include &lt;string.h&gt;
#include &lt;ctype.h&gt;

void ChiffrerCesar(char *texte, int cle)
{
    // Normalisation de la clé entre 0 et 25
    cle = (cle % 26 + 26) % 26;

    for (int i = 0; texte[i] != '\0'; i++)
    {
        if (isupper((unsigned char)texte[i]))
        {
            texte[i] = (texte[i] - 'A' + cle) % 26 + 'A';
        }
        else if (islower((unsigned char)texte[i]))
        {
            texte[i] = (texte[i] - 'a' + cle) % 26 + 'a';
        }
        // Les ponctuations, espaces et chiffres restent inchangés
    }
}

void DechiffrerCesar(char *texte, int cle)
{
    // Déchiffrer revient à chiffrer avec un décalage de 26 - cle
    ChiffrerCesar(texte, 26 - (cle % 26));
}

int main(void)
{
    char message[100] = "Rendez-vous a minuit au laboratoire secret !";
    int cle = 4;

    printf("Message original   : %s\n", message);

    ChiffrerCesar(message, cle);
    printf("Message chiffre (K=%d): %s\n", cle, message);

    DechiffrerCesar(message, cle);
    printf("Message dechiffre  : %s\n", message);

    return 0;
}
